    canonical = value;
    if (canonical < 0 || canonical > 100) return null;
  } else {
    if (unit === 'kpa') canonical = value * 10;
    else canonical = value; // mbar = hPa
    if (canonical < 850 || canonical > 1100) return null;
  }
  canonical = Math.round(canonical * 100) / 100;

  // Derive status
  let status;
  if (metric === 'temperature') {
    if (canonical > 40 || canonical < -5) status = 'critical';
